cat <<'EOF' > app/views/moderate/games/show.html.erb
<% content_for :title, "Quizzy · #{@quiz.title}" %>

<%
  cover_classes = if @game.finished?
    "cover cover--night"
  elsif @game.lobby?
    "cover cover--blue"
  else
    "cover cover--blue cover--calm"
  end
%>

<div class="<%= cover_classes %>"
     data-controller="moderator-game"
     data-moderator-game-state-value="<%= @initial_state.to_json %>"
     data-moderator-game-code-value="<%= @game.code %>"
     data-moderator-game-token-value="<%= @moderator_token %>"
     data-moderator-game-start-url-value="<%= start_moderate_quiz_game_path(@quiz, @game) %>"
     data-moderator-game-finish-url-value="<%= finish_question_moderate_quiz_game_path(@quiz, @game) %>"
     data-moderator-game-next-url-value="<%= next_question_moderate_quiz_game_path(@quiz, @game) %>"
     data-moderator-game-end-url-value="<%= end_quiz_moderate_quiz_game_path(@quiz, @game) %>"
     data-moderator-game-top-winners-url-value="<%= pick_top_winners_moderate_quiz_game_path(@quiz, @game) %>"
     data-moderator-game-draw-winners-url-value="<%= draw_winners_moderate_quiz_game_path(@quiz, @game) %>"
     data-moderator-game-reset-winners-url-value="<%= reset_winners_moderate_quiz_game_path(@quiz, @game) %>"
     data-moderator-game-state-url-value="<%= state_moderate_quiz_game_path(@quiz, @game) %>"
     data-moderator-game-target="cover">
  <div class="screen">
    <div class="screen__top">
      <span class="logo screen__logo"><span class="logo__mark">?</span>Quizzy</span>
      <span><%= @quiz.title %></span>
    </div>

    <div class="screen__body">
      <div class="lobby" data-moderator-game-target="lobby" <%= "hidden" unless @game.lobby? %>>
        <div>
          <h1 class="lobby__title"><%= @quiz.title %></h1>
          <div class="lobby__join">Join at</div>
          <div class="lobby__url"><%= @join_url %></div>
          <div class="counter-pill"><span>Players: <strong data-moderator-game-target="playerCount"><%= @initial_state[:player_count] %></strong></span></div>
        </div>
        <div class="qr" aria-label="QR code for <%= @join_url %>">
          <%= qr_code_svg(@join_url) %>
        </div>
      </div>

      <div data-moderator-game-target="stage" <%= "hidden" if @game.lobby? %>>
        <% if @game.finished? %>
          <% leaderboard = @initial_state[:leaderboard] || [] %>
          <div class="leaderboard-layout">
            <div>
              <div class="screen__kicker">The quiz is over</div>
              <h1 class="leaderboard-layout__title">Leaderboard</h1>
            </div>
            <% if leaderboard.empty? %>
              <p class="play-lead">No players joined.</p>
            <% else %>
              <ol class="leaderboard">
                <% leaderboard.each do |row| %>
                  <li class="leader <%= "is-winner" if row[:winner] %>">
                    <span class="leader__place"><%= row[:place] %></span>
                    <span class="leader__who">
                      <span class="leader__name"><%= row[:name] %></span>
                      <% if row[:winner] %>
                        <span class="leader__badge">Winner</span>
                      <% end %>
                    </span>
                    <span class="leader__score">
                      <%= pluralize(row[:points], "point") %>
                      <% if row[:points] > 0 %>
                        <span class="leader__time"><%= format("%.1fs", row[:correct_time]) %></span>
                      <% end %>
                    </span>
                  </li>
                <% end %>
              </ol>
            <% end %>
          </div>
        <% elsif (@game.question_open? || @game.question_closed?) && @initial_state[:question] %>
          <% q = @initial_state[:question] %>
          <% total_answers = @initial_state[:answered_count].to_i %>
          <div class="stage-question__num">Question <%= q[:index] %> of <%= q[:total] %></div>
          <div class="stage-question__body"><%= q[:body] %></div>
          <ol class="stage-options <%= "stage-options--results" if @game.question_closed? %>">
            <% q[:options].each_with_index do |opt, idx| %>
              <li class="stage-option <%= "is-correct" if @game.question_closed? && opt[:correct] %>">
                <% if @game.question_closed? %>
                  <% share = total_answers.positive? ? (opt[:count].to_f / total_answers * 100).round : 0 %>
                  <div class="stage-option__bar" style="--share: <%= share %>%"></div>
                <% end %>
                <span class="stage-option__letter"><%= option_letter(idx) %></span>
                <span class="stage-option__title"><%= opt[:body] %></span>
                <% if @game.question_closed? && opt[:correct] %>
                  <span class="stage-option__mark">Correct</span>
                <% end %>
                <% if @game.question_closed? %>
                  <span class="stage-option__count"><%= opt[:count] %></span>
                <% end %>
              </li>
            <% end %>
          </ol>
        <% end %>
      </div>
    </div>
  </div>

  <div class="screen-controls">
    <div class="screen-controls__info" data-moderator-game-target="controlsInfo">
      <% unless @game.finished? %>
        <%= link_to "Back to quiz", moderate_quiz_path(@quiz) %>
      <% end %>
      <% if @game.question_open? || @game.question_closed? %>
        <span class="answers-counter">Answers: <%= @initial_state[:answered_count] %> / <%= @initial_state[:player_count] %></span>
      <% end %>
    </div>
    <div class="buttons" data-moderator-game-target="controlsActions">
      <% if @game.lobby? %>
        <button type="button" class="btn btn--pink btn--lg" data-action="moderator-game#start">Start</button>
      <% elsif @game.question_open? %>
        <button type="button" class="btn btn--pink btn--lg" data-action="moderator-game#finishQuestion">Finish</button>
      <% elsif @game.question_closed? %>
        <% if @initial_state[:has_next_question] %>
          <button type="button" class="btn btn--pink btn--lg" data-action="moderator-game#nextQuestion">Next</button>
        <% else %>
          <button type="button" class="btn btn--pink btn--lg" data-action="moderator-game#endQuiz">End quiz</button>
        <% end %>
      <% else %>
        <button type="button" class="btn btn--pink btn--lg" data-action="moderator-game#pickTopWinners">Top <%= @initial_state[:winners_count] %></button>
        <button type="button" class="btn btn--pink btn--lg" data-action="moderator-game#drawWinners">Draw</button>
        <button type="button" class="btn btn--light" data-action="moderator-game#resetWinners">Reset winners</button>
        <%= link_to "Back to quiz", moderate_quiz_path(@quiz), class: "btn btn--light" %>
      <% end %>
    </div>
  </div>
</div>
EOF

cat <<'EOF' > app/javascript/controllers/moderator_game_controller.js
import { Controller } from "@hotwired/stimulus"
import { createConsumer } from "@rails/actioncable"

export default class extends Controller {
  static values = {
    state: Object,
    code: String,
    token: String,
    startUrl: String,
    finishUrl: String,
    nextUrl: String,
    endUrl: String,
    topWinnersUrl: String,
    drawWinnersUrl: String,
    resetWinnersUrl: String,
    stateUrl: String
  }

  static targets = ["cover", "lobby", "stage", "playerCount", "controlsInfo", "controlsActions"]

  connect() {
    this.state = this.stateValue
    const backLink = this.controlsInfoTarget.querySelector("a") || this.controlsActionsTarget.querySelector("a")
    this.backUrl = backLink ? backLink.getAttribute("href") : "/moderate"

    this.consumer = createConsumer()
    this.subscription = this.consumer.subscriptions.create(
      { channel: "ModerateGameChannel", code: this.codeValue, token: this.tokenValue },
      {
        connected: () => {
          this.stopFallbackPolling()
          this.syncState()
        },
        disconnected: () => {
          this.startFallbackPolling()
        },
        received: (data) => {
          this.applyState(data)
        }
      }
    )

    this.onVisibilityChange = () => {
      if (document.visibilityState === "visible") {
        this.syncState()
      }
    }
    document.addEventListener("visibilitychange", this.onVisibilityChange)
  }

  disconnect() {
    this.stopFallbackPolling()
    document.removeEventListener("visibilitychange", this.onVisibilityChange)
    if (this.subscription) {
      this.subscription.unsubscribe()
    }
    if (this.consumer) {
      this.consumer.disconnect()
    }
  }

  start(event) {
    this.performAction(this.startUrlValue, event.currentTarget)
  }

  finishQuestion(event) {
    this.performAction(this.finishUrlValue, event.currentTarget)
  }

  nextQuestion(event) {
    this.performAction(this.nextUrlValue, event.currentTarget)
  }

  endQuiz(event) {
    this.performAction(this.endUrlValue, event.currentTarget)
  }

  pickTopWinners(event) {
    this.performAction(this.topWinnersUrlValue, event.currentTarget)
  }

  drawWinners(event) {
    this.performAction(this.drawWinnersUrlValue, event.currentTarget)
  }

  resetWinners(event) {
    this.performAction(this.resetWinnersUrlValue, event.currentTarget)
  }

  async performAction(url, button) {
    if (button) button.disabled = true
    try {
      const response = await fetch(url, {
        method: "POST",
        headers: {
          "Accept": "application/json",
          "Content-Type": "application/json",
          "X-CSRF-Token": this.csrfToken()
        },
        body: "{}"
      })
      if (response.ok) {
        const data = await response.json()
        this.applyState(data)
      }
    } catch (_err) {
      this.syncState()
    } finally {
      if (button && button.isConnected) button.disabled = false
    }
  }

  async syncState() {
    try {
      const url = `${this.stateUrlValue}?since_version=${encodeURIComponent(this.state.version)}`
      const response = await fetch(url, {
        headers: { "Accept": "application/json" },
        cache: "no-store"
      })
      if (response.status === 200) {
        const data = await response.json()
        this.applyState(data)
      }
    } catch (_err) {
      // Will retry on next poll or reconnect
    }
  }

  startFallbackPolling() {
    if (this.pollTimer) return
    this.pollTimer = setInterval(() => this.syncState(), 2000)
  }

  stopFallbackPolling() {
    if (this.pollTimer) {
      clearInterval(this.pollTimer)
      this.pollTimer = null
    }
  }

  applyState(nextState) {
    if (!nextState || typeof nextState.version !== "number") return
    if (nextState.version <= this.state.version) return

    this.state = nextState
    this.render()
  }

  render() {
    const status = this.state.status

    if (status === "finished") {
      this.coverTarget.className = "cover cover--night"
    } else if (status === "lobby") {
      this.coverTarget.className = "cover cover--blue"
    } else {
      this.coverTarget.className = "cover cover--blue cover--calm"
    }

    if (status === "lobby") {
      this.lobbyTarget.hidden = false
      this.stageTarget.hidden = true
      this.playerCountTarget.textContent = String(this.state.player_count)
    } else {
      this.lobbyTarget.hidden = true
      this.stageTarget.hidden = false
      this.renderStage()
    }

    this.renderControls()
  }

  renderStage() {
    this.stageTarget.replaceChildren()

    if (this.state.status === "finished") {
      const layout = document.createElement("div")
      layout.className = "leaderboard-layout"

      const header = document.createElement("div")
      const kicker = document.createElement("div")
      kicker.className = "screen__kicker"
      kicker.textContent = "The quiz is over"
      const h1 = document.createElement("h1")
      h1.className = "leaderboard-layout__title"
      h1.textContent = "Leaderboard"
      header.append(kicker, h1)
      layout.appendChild(header)

      const leaderboard = this.state.leaderboard || []
      if (leaderboard.length === 0) {
        const empty = document.createElement("p")
        empty.className = "play-lead"
        empty.textContent = "No players joined."
        layout.appendChild(empty)
      } else {
        const list = document.createElement("ol")
        list.className = "leaderboard"

        leaderboard.forEach((row) => {
          const li = document.createElement("li")
          li.className = row.winner ? "leader is-winner" : "leader"

          const placeEl = document.createElement("span")
          placeEl.className = "leader__place"
          placeEl.textContent = String(row.place)

          const whoEl = document.createElement("span")
          whoEl.className = "leader__who"
          const nameEl = document.createElement("span")
          nameEl.className = "leader__name"
          nameEl.textContent = row.name
          whoEl.appendChild(nameEl)

          if (row.winner) {
            const badgeEl = document.createElement("span")
            badgeEl.className = "leader__badge"
            badgeEl.textContent = "Winner"
            whoEl.appendChild(badgeEl)
          }

          const scoreEl = document.createElement("span")
          scoreEl.className = "leader__score"
          const pointsText = row.points === 1 ? "1 point" : `${row.points} points`
          scoreEl.appendChild(document.createTextNode(pointsText))

          if (row.points > 0 && row.correct_time != null) {
            const timeEl = document.createElement("span")
            timeEl.className = "leader__time"
            timeEl.textContent = `${Number(row.correct_time).toFixed(1)}s`
            scoreEl.appendChild(timeEl)
          }

          li.append(placeEl, whoEl, scoreEl)
          list.appendChild(li)
        })

        layout.appendChild(list)
      }

      this.stageTarget.appendChild(layout)
      return
    }

    const q = this.state.question
    if (!q) return

    const isClosed = this.state.status === "question_closed"
    const totalAnswers = Number(this.state.answered_count || 0)

    const numEl = document.createElement("div")
    numEl.className = "stage-question__num"
    numEl.textContent = `Question ${q.index} of ${q.total}`

    const bodyEl = document.createElement("div")
    bodyEl.className = "stage-question__body"
    bodyEl.textContent = q.body

    const listEl = document.createElement("ol")
    listEl.className = isClosed ? "stage-options stage-options--results" : "stage-options"

    q.options.forEach((opt, idx) => {
      const li = document.createElement("li")
      li.className = "stage-option"
      if (isClosed && opt.correct) {
        li.classList.add("is-correct")
      }

      if (isClosed) {
        const count = Number(opt.count || 0)
        const share = totalAnswers > 0 ? Math.round((count / totalAnswers) * 100) : 0
        const barEl = document.createElement("div")
        barEl.className = "stage-option__bar"
        barEl.style.setProperty("--share", `${share}%`)
        li.appendChild(barEl)
      }

      const letterEl = document.createElement("span")
      letterEl.className = "stage-option__letter"
      letterEl.textContent = idx < 26 ? String.fromCharCode(65 + idx) : String(idx + 1)

      const titleEl = document.createElement("span")
      titleEl.className = "stage-option__title"
      titleEl.textContent = opt.body

      li.append(letterEl, titleEl)

      if (isClosed) {
        if (opt.correct) {
          const markEl = document.createElement("span")
          markEl.className = "stage-option__mark"
          markEl.textContent = "Correct"
          li.appendChild(markEl)
        }
        const countEl = document.createElement("span")
        countEl.className = "stage-option__count"
        countEl.textContent = String(opt.count || 0)
        li.appendChild(countEl)
      }

      listEl.appendChild(li)
    })

    this.stageTarget.append(numEl, bodyEl, listEl)
  }

  renderControls() {
    this.controlsInfoTarget.replaceChildren()
    if (this.state.status !== "finished") {
      const backLink = document.createElement("a")
      backLink.href = this.backUrl
      backLink.textContent = "Back to quiz"
      this.controlsInfoTarget.appendChild(backLink)
    }

    if (this.state.status === "question_open" || this.state.status === "question_closed") {
      const counter = document.createElement("span")
      counter.className = "answers-counter"
      counter.textContent = `Answers: ${this.state.answered_count} / ${this.state.player_count}`
      this.controlsInfoTarget.appendChild(counter)
    }

    this.controlsActionsTarget.replaceChildren()
    if (this.state.status === "lobby") {
      this.controlsActionsTarget.appendChild(this.makeActionButton("Start", "moderator-game#start"))
    } else if (this.state.status === "question_open") {
      this.controlsActionsTarget.appendChild(this.makeActionButton("Finish", "moderator-game#finishQuestion"))
    } else if (this.state.status === "question_closed") {
      if (this.state.has_next_question) {
        this.controlsActionsTarget.appendChild(this.makeActionButton("Next", "moderator-game#nextQuestion"))
      } else {
        this.controlsActionsTarget.appendChild(this.makeActionButton("End quiz", "moderator-game#endQuiz"))
      }
    } else {
      const n = this.state.winners_count || 3
      this.controlsActionsTarget.appendChild(this.makeActionButton(`Top ${n}`, "moderator-game#pickTopWinners"))
      this.controlsActionsTarget.appendChild(this.makeActionButton("Draw", "moderator-game#drawWinners"))
      this.controlsActionsTarget.appendChild(this.makeActionButton("Reset winners", "moderator-game#resetWinners", "btn btn--light"))

      const doneLink = document.createElement("a")
      doneLink.href = this.backUrl
      doneLink.className = "btn btn--light"
      doneLink.textContent = "Back to quiz"
      this.controlsActionsTarget.appendChild(doneLink)
    }
  }

  makeActionButton(label, action, className = "btn btn--pink btn--lg") {
    const btn = document.createElement("button")
    btn.type = "button"
    btn.className = className
    btn.dataset.action = action
    btn.textContent = label
    return btn
  }

  csrfToken() {
    const meta = document.querySelector('meta[name="csrf-token"]')
    return meta ? meta.getAttribute("content") : ""
  }
}
EOF

