cat <<'EOF' > app/views/play/show.html.erb
<% content_for :title, "Quizzy · #{@game.quiz.title}" %>

<%
  is_question = @player.present? && (@game.question_open? || @game.question_closed?) && @initial_state[:question].present?
%>

<main class="play"
      data-controller="player-game"
      data-player-game-state-value="<%= @initial_state.to_json %>"
      data-player-game-code-value="<%= @game.code %>"
      data-player-game-joined-value="<%= @player.present? %>"
      <% if @player %>data-player-game-player-id-value="<%= @player.id %>"<% end %>
      data-player-game-answer-url-value="<%= play_answer_path(@game.code) %>"
      data-player-game-state-url-value="<%= play_state_path(@game.code) %>">
  <div class="play__top">
    <span class="logo play__logo"><span class="logo__mark">?</span>Quizzy</span>
    <span><%= @player ? @player.name : @game.quiz.title %></span>
  </div>

  <div class="play__body <%= "play__body--top" if is_question %>" data-player-game-target="stage">
    <% if @game.finished? %>
      <% result = @player ? @initial_state[:player_result] : nil %>
      <% if result %>
        <div class="waiting" style="margin-bottom: 24px">
          <h2>The quiz is over</h2>
        </div>
        <div class="card result-card">
          <div class="result-card__place"><%= result[:place] %></div>
          <div class="result-card__label">Place <%= result[:place] %> of <%= result[:total_players] %></div>
          <div class="result-card__score"><%= pluralize(result[:points], "point") %></div>
          <% if result[:winner] %>
            <div class="winner-banner">You won!</div>
          <% end %>
        </div>
      <% else %>
        <div class="waiting">
          <div class="waiting__gem">?</div>
          <h2>The quiz is over</h2>
        </div>
      <% end %>
    <% elsif @player.nil? %>
      <h1 class="play-title"><%= @game.quiz.title %></h1>

      <% if @join_error.present? %>
        <div class="errors">
          <ul>
            <li><%= @join_error %></li>
          </ul>
        </div>
      <% end %>

      <%= form_with url: play_join_path(@game.code), method: :post, class: "join-form" do %>
        <label for="player_name" class="field-label">Your name</label>
        <input id="player_name"
               type="text"
               name="name"
               class="input"
               placeholder="Your name"
               value="<%= params[:name] %>"
               required
               autofocus
               autocomplete="nickname">
        <button type="submit" class="btn btn--pink">Join</button>
      <% end %>
    <% elsif @game.lobby? %>
      <div class="waiting">
        <div class="waiting__gem">?</div>
        <h2>Hi, <%= @player.name %>!</h2>
        <p class="play-lead">Waiting for the quiz to start…</p>
      </div>
    <% elsif is_question %>
      <% q = @initial_state[:question] %>
      <% picked_id = @initial_state[:picked_option_id] %>
      <div class="play-question__num">Question <%= q[:index] %> of <%= q[:total] %></div>
      <div class="play-question__body"><%= q[:body] %></div>

      <% if @game.question_open? %>
        <div class="play-options">
          <% q[:options].each_with_index do |opt, idx| %>
            <% is_picked = picked_id == opt[:id] %>
            <button type="button"
                    class="play-option <%= "is-picked" if is_picked %>"
                    data-option-id="<%= opt[:id] %>"
                    data-question-id="<%= q[:id] %>"
                    data-action="player-game#pickOption">
              <span class="play-option__letter"><%= option_letter(idx) %></span>
              <span class="play-option__title"><%= opt[:body] %></span>
              <span class="play-option__mark"><%= "Your answer" if is_picked %></span>
            </button>
          <% end %>
        </div>
      <% else %>
        <div class="play-options is-locked is-revealed">
          <% q[:options].each_with_index do |opt, idx| %>
            <% is_picked = picked_id == opt[:id] %>
            <% is_correct = opt[:correct] %>
            <button type="button"
                    class="play-option <%= "is-picked" if is_picked %> <%= "is-correct" if is_correct %>"
                    disabled>
              <span class="play-option__letter"><%= option_letter(idx) %></span>
              <span class="play-option__title"><%= opt[:body] %></span>
              <span class="play-option__mark"><%= is_picked ? "Your answer" : (is_correct ? "✓" : "") %></span>
            </button>
          <% end %>
        </div>

        <% picked_opt = q[:options].find { |o| o[:id] == picked_id } %>
        <% if picked_opt.nil? %>
          <div class="play-status play-status--neutral">No answer</div>
        <% elsif picked_opt[:correct] %>
          <div class="play-status play-status--right">Correct!</div>
        <% else %>
          <div class="play-status play-status--wrong">Wrong!</div>
        <% end %>
      <% end %>
    <% end %>
  </div>
</main>
EOF

cat <<'EOF' > app/javascript/controllers/player_game_controller.js
import { Controller } from "@hotwired/stimulus"
import { createConsumer } from "@rails/actioncable"

export default class extends Controller {
  static values = {
    state: Object,
    code: String,
    joined: Boolean,
    playerId: Number,
    answerUrl: String,
    stateUrl: String
  }

  static targets = ["stage"]

  connect() {
    this.state = this.stateValue
    this.pickedByQuestion = {}
    this.latestPickSeq = 0

    if (this.state.question && this.state.picked_option_id != null) {
      this.pickedByQuestion[this.state.question.id] = this.state.picked_option_id
    }

    this.consumer = createConsumer()
    this.subscription = this.consumer.subscriptions.create(
      { channel: "PlayerGameChannel", code: this.codeValue },
      {
        connected: () => {
          this.stopFallbackPolling()
          this.syncState()
        },
        disconnected: () => {
          this.startFallbackPolling()
        },
        received: (data) => {
          this.applyState(data)
        }
      }
    )

    this.onVisibilityChange = () => {
      if (document.visibilityState === "visible") {
        this.syncState()
      }
    }
    document.addEventListener("visibilitychange", this.onVisibilityChange)
  }

  disconnect() {
    this.stopFallbackPolling()
    document.removeEventListener("visibilitychange", this.onVisibilityChange)
    if (this.subscription) {
      this.subscription.unsubscribe()
    }
    if (this.consumer) {
      this.consumer.disconnect()
    }
  }

  async syncState() {
    try {
      const url = `${this.stateUrlValue}?since_version=${encodeURIComponent(this.state.version)}`
      const response = await fetch(url, {
        headers: { "Accept": "application/json" },
        cache: "no-store"
      })
      if (response.status === 200) {
        const data = await response.json()
        this.applyState(data)
      }
    } catch (_err) {
      // Will retry on next poll or reconnect
    }
  }

  startFallbackPolling() {
    if (this.pollTimer) return
    this.pollTimer = setInterval(() => this.syncState(), 2000)
  }

  stopFallbackPolling() {
    if (this.pollTimer) {
      clearInterval(this.pollTimer)
      this.pollTimer = null
    }
  }

  applyState(nextState) {
    if (!nextState || typeof nextState.version !== "number") return
    if (nextState.version < this.state.version) return

    if (nextState.question && nextState.picked_option_id != null) {
      if (this.pickedByQuestion[nextState.question.id] == null || nextState.version > this.state.version) {
        this.pickedByQuestion[nextState.question.id] = nextState.picked_option_id
      }
    }

    const sameVersion = nextState.version === this.state.version
    const sameStatus = nextState.status === this.state.status
    const nextQuestionId = nextState.question ? nextState.question.id : null
    const currQuestionId = this.state.question ? this.state.question.id : null
    if (sameVersion && sameStatus && nextQuestionId === currQuestionId) {
      return
    }

    const playerName = nextState.player_name || this.state.player_name
    this.state = { ...nextState, player_name: playerName }

    if (!this.joinedValue) {
      if (this.state.status === "finished") {
        this.renderFinished()
      }
      return
    }

    this.render()
  }

  pickOption(event) {
    if (this.state.status !== "question_open" || !this.state.question) return

    const button = event.currentTarget
    const qId = Number(button.dataset.questionId)
    const optionId = Number(button.dataset.optionId)
    if (this.state.question.id !== qId) return

    this.pickedByQuestion[qId] = optionId
    const seq = ++this.latestPickSeq
    this.updateOpenOptionsSelection(optionId)
    this.sendAnswerWithRetry(qId, optionId, seq, 0)
  }

  updateOpenOptionsSelection(pickedId) {
    const buttons = this.stageTarget.querySelectorAll("button.play-option")
    buttons.forEach((btn) => {
      const optId = Number(btn.dataset.optionId)
      const isPicked = optId === pickedId
      btn.classList.toggle("is-picked", isPicked)
      const mark = btn.querySelector(".play-option__mark")
      if (mark) {
        mark.textContent = isPicked ? "Your answer" : ""
      }
    })
  }

  async sendAnswerWithRetry(qId, optionId, seq, attempt) {
    try {
      const response = await fetch(this.answerUrlValue, {
        method: "POST",
        headers: {
          "Accept": "application/json",
          "Content-Type": "application/json",
          "X-CSRF-Token": this.csrfToken()
        },
        body: JSON.stringify({
          game_question_id: qId,
          game_option_id: optionId
        })
      })

      if (seq !== this.latestPickSeq) return

      if (response.ok) {
        const data = await response.json()
        if (data.picked_option_id != null) {
          this.pickedByQuestion[qId] = data.picked_option_id
        }
        return
      }

      if (response.status === 409) {
        const data = await response.json()
        if (data.state) {
          if (data.state.question && data.state.picked_option_id !== undefined) {
            this.pickedByQuestion[data.state.question.id] = data.state.picked_option_id
          }
          this.applyState(data.state)
        }
        return
      }

      if (response.status >= 500 && attempt < 3) {
        this.scheduleRetry(qId, optionId, seq, attempt)
      }
    } catch (_err) {
      if (seq === this.latestPickSeq && attempt < 3) {
        this.scheduleRetry(qId, optionId, seq, attempt)
      }
    }
  }

  scheduleRetry(qId, optionId, seq, attempt) {
    const delay = 500 * (2 ** attempt)
    setTimeout(() => {
      if (seq !== this.latestPickSeq) return
      if (this.state.status !== "question_open") return
      if (!this.state.question || this.state.question.id !== qId) return
      this.sendAnswerWithRetry(qId, optionId, seq, attempt + 1)
    }, delay)
  }

  render() {
    const status = this.state.status

    if (status === "finished") {
      this.renderFinished()
      return
    }

    if (status === "lobby") {
      this.stageTarget.className = "play__body"
      this.stageTarget.replaceChildren()

      const wrapper = document.createElement("div")
      wrapper.className = "waiting"

      const gem = document.createElement("div")
      gem.className = "waiting__gem"
      gem.textContent = "?"

      const greeting = document.createElement("h2")
      greeting.textContent = `Hi, ${this.state.player_name}!`

      const lead = document.createElement("p")
      lead.className = "play-lead"
      lead.textContent = "Waiting for the quiz to start…"

      wrapper.append(gem, greeting, lead)
      this.stageTarget.appendChild(wrapper)
      return
    }

    const q = this.state.question
    if (!q) return

    this.stageTarget.className = "play__body play__body--top"
    this.stageTarget.replaceChildren()

    const numEl = document.createElement("div")
    numEl.className = "play-question__num"
    numEl.textContent = `Question ${q.index} of ${q.total}`

    const bodyEl = document.createElement("div")
    bodyEl.className = "play-question__body"
    bodyEl.textContent = q.body

    const isClosed = status === "question_closed"
    const pickedId = this.pickedByQuestion[q.id] ?? null

    const optionsEl = document.createElement("div")
    optionsEl.className = isClosed ? "play-options is-locked is-revealed" : "play-options"

    q.options.forEach((opt, idx) => {
      const btn = document.createElement("button")
      btn.type = "button"
      btn.className = "play-option"
      const isPicked = pickedId === opt.id
      if (isPicked) btn.classList.add("is-picked")

      if (isClosed) {
        btn.disabled = true
        if (opt.correct) btn.classList.add("is-correct")
      } else {
        btn.dataset.optionId = opt.id
        btn.dataset.questionId = q.id
        btn.dataset.action = "player-game#pickOption"
      }

      const letterEl = document.createElement("span")
      letterEl.className = "play-option__letter"
      letterEl.textContent = idx < 26 ? String.fromCharCode(65 + idx) : String(idx + 1)

      const titleEl = document.createElement("span")
      titleEl.className = "play-option__title"
      titleEl.textContent = opt.body

      const markEl = document.createElement("span")
      markEl.className = "play-option__mark"
      if (isPicked) {
        markEl.textContent = "Your answer"
      } else if (isClosed && opt.correct) {
        markEl.textContent = "✓"
      }

      btn.append(letterEl, titleEl, markEl)
      optionsEl.appendChild(btn)
    })

    this.stageTarget.append(numEl, bodyEl, optionsEl)

    if (isClosed) {
      const pickedOpt = q.options.find((o) => o.id === pickedId)
      const statusEl = document.createElement("div")
      if (!pickedOpt) {
        statusEl.className = "play-status play-status--neutral"
        statusEl.textContent = "No answer"
      } else if (pickedOpt.correct) {
        statusEl.className = "play-status play-status--right"
        statusEl.textContent = "Correct!"
      } else {
        statusEl.className = "play-status play-status--wrong"
        statusEl.textContent = "Wrong!"
      }
      this.stageTarget.appendChild(statusEl)
    }
  }

  renderFinished() {
    this.stageTarget.className = "play__body"
    this.stageTarget.replaceChildren()

    const result = this.state.player_result ||
      (this.hasPlayerIdValue && this.playerIdValue && this.state.player_results
        ? this.state.player_results[String(this.playerIdValue)]
        : null)

    if (this.joinedValue && result) {
      const header = document.createElement("div")
      header.className = "waiting"
      header.style.marginBottom = "24px"
      const h2 = document.createElement("h2")
      h2.textContent = "The quiz is over"
      header.appendChild(h2)

      const card = document.createElement("div")
      card.className = "card result-card"

      const placeEl = document.createElement("div")
      placeEl.className = "result-card__place"
      placeEl.textContent = String(result.place)

      const labelEl = document.createElement("div")
      labelEl.className = "result-card__label"
      labelEl.textContent = `Place ${result.place} of ${result.total_players}`

      const scoreEl = document.createElement("div")
      scoreEl.className = "result-card__score"
      scoreEl.textContent = result.points === 1 ? "1 point" : `${result.points} points`

      card.append(placeEl, labelEl, scoreEl)

      if (result.winner) {
        const banner = document.createElement("div")
        banner.className = "winner-banner"
        banner.textContent = "You won!"
        card.appendChild(banner)
      }

      this.stageTarget.append(header, card)
      return
    }

    const wrapper = document.createElement("div")
    wrapper.className = "waiting"

    const gem = document.createElement("div")
    gem.className = "waiting__gem"
    gem.textContent = "?"

    const h2 = document.createElement("h2")
    h2.textContent = "The quiz is over"

    wrapper.append(gem, h2)
    this.stageTarget.appendChild(wrapper)
  }

  csrfToken() {
    const meta = document.querySelector('meta[name="csrf-token"]')
    return meta ? meta.getAttribute("content") : ""
  }
}
EOF

